CREATE TABLE inventory_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), product_id uuid NOT NULL, transaction_type text NOT NULL CHECK (transaction_type IN ('PURCHASE','SALE','RETURN','ADJUSTMENT','DAMAGE')), quantity numeric(18,3) NOT NULL CHECK(quantity>0), reference_type text, reference_id uuid, timestamp timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id,product_id) REFERENCES products(organization_id,id)); CREATE INDEX inventory_tx_product_time_idx ON inventory_transactions(organization_id,product_id,timestamp DESC);
